def my_pow(x: float, n: int) -> float:
    if n < 0:
        return 1 / my_pow(x, -n)  # x^-n = 1 / x^n
    if n == 0:
        return 1.0  # base case: stops the recursion
    half = my_pow(x, n // 2)  # ONE call on half the exponent
    if n % 2 == 0:
        return half * half  # even: x^n = half * half
    return half * half * x  # odd: one extra factor of x

public double myPow(double x, int n) {
    long N = n; // widen first: -(-2^31) does not fit in an int
    return N < 0 ? 1 / pow(x, -N) : pow(x, N);
}

private double pow(double x, long n) {
    if (n == 0) return 1.0; // base case: stops the recursion
    double half = pow(x, n / 2); // ONE call on half the exponent
    return n % 2 == 0 ? half * half : half * half * x;
}

