function permute(nums) {
  const result = [];
  const path = [];
  const used = new Array(nums.length).fill(false);
  function backtrack() {
    if (path.length === nums.length) {
      result.push([...path]); // complete permutation: record a copy
      return;
    }
    for (let i = 0; i < nums.length; i++) {
      if (used[i]) continue; // already placed earlier in path
      used[i] = true;
      path.push(nums[i]); // choose
      backtrack(); // explore
      path.pop(); // un-choose
      used[i] = false;
    }
  }
  backtrack();
  return result;
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    backtrack(nums, new boolean[nums.length], new ArrayList<>(), result);
    return result;
}

private void backtrack(int[] nums, boolean[] used, List<Integer> path, List<List<Integer>> result) {
    if (path.size() == nums.length) {
        result.add(new ArrayList<>(path)); // complete permutation: record a copy
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (used[i]) continue; // already placed earlier in path
        used[i] = true;
        path.add(nums[i]); // choose
        backtrack(nums, used, path, result); // explore
        path.remove(path.size() - 1); // un-choose
        used[i] = false;
    }
}

function combinationSum(candidates, target) {
  const nums = [...candidates].sort((a, b) => a - b); // sorted: enables break
  const result = [];
  const path = [];
  function backtrack(start, remaining) {
    if (remaining === 0) {
      result.push([...path]); // exact sum reached
      return;
    }
    for (let i = start; i < nums.length; i++) {
      if (nums[i] > remaining) break; // later candidates are even larger
      path.push(nums[i]); // choose
      backtrack(i, remaining - nums[i]); // i, not i + 1: reuse allowed
      path.pop(); // un-choose
    }
  }
  backtrack(0, target);
  return result;
}

def combination_sum(candidates: list[int], target: int) -> list[list[int]]:
    nums = sorted(candidates)  # sorted: enables break
    result, path = [], []

    def backtrack(start: int, remaining: int) -> None:
        if remaining == 0:
            result.append(path[:])  # exact sum reached
            return
        for i in range(start, len(nums)):
            if nums[i] > remaining:
                break  # later candidates are even larger
            path.append(nums[i])  # choose
            backtrack(i, remaining - nums[i])  # i, not i + 1: reuse allowed
            path.pop()  # un-choose

    backtrack(0, target)
    return result

public List<List<Integer>> combinationSum(int[] candidates, int target) {
    int[] nums = candidates.clone();
    Arrays.sort(nums); // sorted: enables break
    List<List<Integer>> result = new ArrayList<>();
    backtrack(nums, 0, target, new ArrayList<>(), result);
    return result;
}

private void backtrack(int[] nums, int start, int remaining, List<Integer> path, List<List<Integer>> result) {
    if (remaining == 0) {
        result.add(new ArrayList<>(path)); // exact sum reached
        return;
    }
    for (int i = start; i < nums.length; i++) {
        if (nums[i] > remaining) break; // later candidates are even larger
        path.add(nums[i]); // choose
        backtrack(nums, i, remaining - nums[i], path, result); // i: reuse allowed
        path.remove(path.size() - 1); // un-choose
    }
}

function generateParenthesis(n) {
  const result = [];
  const path = [];
  function backtrack(open, close) {
    if (path.length === 2 * n) {
      result.push(path.join('')); // complete and valid
      return;
    }
    if (open < n) { // an opening bracket is still available
      path.push('(');
      backtrack(open + 1, close);
      path.pop();
    }
    if (close < open) { // only close a bracket that is open
      path.push(')');
      backtrack(open, close + 1);
      path.pop();
    }
  }
  backtrack(0, 0);
  return result;
}

public List<String> generateParenthesis(int n) {
    List<String> result = new ArrayList<>();
    backtrack(n, 0, 0, new StringBuilder(), result);
    return result;
}

private void backtrack(int n, int open, int close, StringBuilder path, List<String> result) {
    if (path.length() == 2 * n) {
        result.add(path.toString()); // complete and valid
        return;
    }
    if (open < n) { // an opening bracket is still available
        path.append('(');
        backtrack(n, open + 1, close, path, result);
        path.deleteCharAt(path.length() - 1);
    }
    if (close < open) { // only close a bracket that is open
        path.append(')');
        backtrack(n, open, close + 1, path, result);
        path.deleteCharAt(path.length() - 1);
    }
}

function letterCombinations(digits) {
  if (digits.length === 0) return [];
  const keys = { 2: 'abc', 3: 'def', 4: 'ghi', 5: 'jkl', 6: 'mno', 7: 'pqrs', 8: 'tuv', 9: 'wxyz' };
  const result = [];
  const path = [];
  function backtrack(i) {
    if (i === digits.length) {
      result.push(path.join('')); // one letter chosen for every digit
      return;
    }
    for (const ch of keys[digits[i]]) {
      path.push(ch); // choose a letter for digits[i]
      backtrack(i + 1); // move on to the next digit
      path.pop(); // un-choose
    }
  }
  backtrack(0);
  return result;
}

def letter_combinations(digits: str) -> list[str]:
    if not digits:
        return []
    keys = {'2': 'abc', '3': 'def', '4': 'ghi', '5': 'jkl',
            '6': 'mno', '7': 'pqrs', '8': 'tuv', '9': 'wxyz'}
    result, path = [], []

    def backtrack(i: int) -> None:
        if i == len(digits):
            result.append(''.join(path))  # one letter chosen for every digit
            return
        for ch in keys[digits[i]]:
            path.append(ch)  # choose a letter for digits[i]
            backtrack(i + 1)  # move on to the next digit
            path.pop()  # un-choose

    backtrack(0)
    return result

private static final String[] KEYS = {"", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"};

public List<String> letterCombinations(String digits) {
    List<String> result = new ArrayList<>();
    if (digits.isEmpty()) return result;
    backtrack(digits, 0, new StringBuilder(), result);
    return result;
}

private void backtrack(String digits, int i, StringBuilder path, List<String> result) {
    if (i == digits.length()) {
        result.add(path.toString()); // one letter chosen for every digit
        return;
    }
    for (char ch : KEYS[digits.charAt(i) - '0'].toCharArray()) {
        path.append(ch); // choose a letter for digits[i]
        backtrack(digits, i + 1, path, result); // move on to the next digit
        path.deleteCharAt(path.length() - 1); // un-choose
    }
}

function solveNQueens(n) {
  const result = [];
  const queens = []; // queens[r] = column of the queen in row r
  const cols = new Set(), diag = new Set(), anti = new Set();
  function place(r) {
    if (r === n) {
      result.push(queens.map((c) => '.'.repeat(c) + 'Q' + '.'.repeat(n - c - 1)));
      return;
    }
    for (let c = 0; c < n; c++) {
      if (cols.has(c) || diag.has(r - c) || anti.has(r + c)) continue; // attacked
      queens.push(c); // place the queen and block its column and diagonals
      cols.add(c);
      diag.add(r - c);
      anti.add(r + c);
      place(r + 1); // fill the next row
      queens.pop(); // remove it again (backtrack)
      cols.delete(c);
      diag.delete(r - c);
      anti.delete(r + c);
    }
  }
  place(0);
  return result;
}

public List<List<String>> solveNQueens(int n) {
    List<List<String>> result = new ArrayList<>();
    place(0, n, new int[n], new boolean[n], new boolean[2 * n - 1], new boolean[2 * n - 1], result);
    return result;
}

private void place(int r, int n, int[] queens, boolean[] cols, boolean[] diag, boolean[] anti,
                   List<List<String>> result) {
    if (r == n) {
        List<String> board = new ArrayList<>();
        for (int c : queens) board.add(".".repeat(c) + "Q" + ".".repeat(n - c - 1));
        result.add(board);
        return;
    }
    for (int c = 0; c < n; c++) {
        int d = r - c + n - 1, a = r + c; // shift r - c into 0..2n-2
        if (cols[c] || diag[d] || anti[a]) continue; // attacked
        queens[r] = c;
        cols[c] = diag[d] = anti[a] = true; // place the queen
        place(r + 1, n, queens, cols, diag, anti, result);
        cols[c] = diag[d] = anti[a] = false; // remove it again (backtrack)
    }
}

function exist(board, word) {
  const rows = board.length, cols = board[0].length;
  function dfs(r, c, k) {
    if (k === word.length) return true; // matched every character
    if (r < 0 || c < 0 || r >= rows || c >= cols) return false; // off the board
    if (board[r][c] !== word[k]) return false; // wrong letter or already used ('#')
    const saved = board[r][c];
    board[r][c] = '#'; // mark as used on the current path
    const found = dfs(r + 1, c, k + 1) || dfs(r - 1, c, k + 1) ||
      dfs(r, c + 1, k + 1) || dfs(r, c - 1, k + 1);
    board[r][c] = saved; // backtrack: free the cell for other paths
    return found;
  }
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (dfs(r, c, 0)) return true;
    }
  }
  return false;
}

