    rows, cols = len(board), len(board[0])

    def dfs(r: int, c: int, k: int) -> bool:
        if k == len(word):
            return True  # matched every character
        if r < 0 or c < 0 or r >= rows or c >= cols:
            return False  # off the board
        if board[r][c] != word[k]:
            return False  # wrong letter or already used ('#')
        saved, board[r][c] = board[r][c], '#'  # mark as used on the current path
        found = (dfs(r + 1, c, k + 1) or dfs(r - 1, c, k + 1) or
                 dfs(r, c + 1, k + 1) or dfs(r, c - 1, k + 1))
        board[r][c] = saved  # backtrack: free the cell for other paths
        return found

    return any(dfs(r, c, 0) for r in range(rows) for c in range(cols))

public boolean exist(char[][] board, String word) {
    for (int r = 0; r < board.length; r++)
        for (int c = 0; c < board[0].length; c++)
            if (dfs(board, word, r, c, 0)) return true;
    return false;
}

private boolean dfs(char[][] board, String word, int r, int c, int k) {
    if (k == word.length()) return true; // matched every character
    if (r < 0 || c < 0 || r >= board.length || c >= board[0].length) return false; // off the board
    if (board[r][c] != word.charAt(k)) return false; // wrong letter or already used ('#')
    char saved = board[r][c];
    board[r][c] = '#'; // mark as used on the current path
    boolean found = dfs(board, word, r + 1, c, k + 1) || dfs(board, word, r - 1, c, k + 1)
            || dfs(board, word, r, c + 1, k + 1) || dfs(board, word, r, c - 1, k + 1);
    board[r][c] = saved; // backtrack: free the cell for other paths
    return found;
}

function findWords(board, words) {
  const root = { next: new Map(), word: null };
  for (const w of words) {
    let node = root;
    for (const ch of w) {
      if (!node.next.has(ch)) node.next.set(ch, { next: new Map(), word: null });
      node = node.next.get(ch);
    }
    node.word = w; // the node where a word ends stores the whole word
  }
  const rows = board.length, cols = board[0].length;
  const found = [];
  function dfs(r, c, parent) {
    const ch = board[r][c];
    const node = parent.next.get(ch); // '#' (cell in use) is never a trie key
    if (!node) return; // no remaining word continues with ch: prune
    if (node.word !== null) {
      found.push(node.word);
      node.word = null; // report each word only once
    }
    board[r][c] = '#'; // mark as used on the current path
    if (r > 0) dfs(r - 1, c, node);
    if (c > 0) dfs(r, c - 1, node);
    if (r < rows - 1) dfs(r + 1, c, node);
    if (c < cols - 1) dfs(r, c + 1, node);
    board[r][c] = ch; // backtrack: free the cell for other paths
    if (node.next.size === 0 && node.word === null) parent.next.delete(ch); // prune a used-up leaf
  }
  for (let r = 0; r < rows; r++)
    for (let c = 0; c < cols; c++) dfs(r, c, root);
  return found;
}

def find_words(board: list[list[str]], words: list[str]) -> list[str]:
    root: dict = {}
    for w in words:
        node = root
        for ch in w:
            node = node.setdefault(ch, {})
        node['$'] = w  # '$' marks the node where a word ends and stores the word
    rows, cols = len(board), len(board[0])
    found = []

    def dfs(r: int, c: int, parent: dict) -> None:
        ch = board[r][c]
        node = parent.get(ch)  # '#' (cell in use) is never a trie key
        if node is None:
            return  # no remaining word continues with ch: prune
        if '$' in node:
            found.append(node.pop('$'))  # report each word only once
        board[r][c] = '#'  # mark as used on the current path
        for nr, nc in ((r - 1, c), (r, c - 1), (r + 1, c), (r, c + 1)):
            if 0 <= nr < rows and 0 <= nc < cols:
                dfs(nr, nc, node)
        board[r][c] = ch  # backtrack: free the cell for other paths
        if not node:
            del parent[ch]  # prune a used-up leaf: no children and no word left

    for r in range(rows):
        for c in range(cols):
            dfs(r, c, root)
    return found

public List<String> findWords(char[][] board, String[] words) {
    TrieNode root = new TrieNode();
    for (String w : words) {
        TrieNode node = root;
        for (char ch : w.toCharArray()) node = node.next.computeIfAbsent(ch, k -> new TrieNode());
        node.word = w; // the node where a word ends stores the whole word
    }
    List<String> found = new ArrayList<>();
    for (int r = 0; r < board.length; r++)
        for (int c = 0; c < board[0].length; c++) dfs(board, r, c, root, found);
    return found;
}

private void dfs(char[][] board, int r, int c, TrieNode parent, List<String> found) {
    if (r < 0 || c < 0 || r >= board.length || c >= board[0].length) return; // off the board
    char ch = board[r][c];
    TrieNode node = parent.next.get(ch); // '#' (cell in use) is never a trie key
    if (node == null) return; // no remaining word continues with ch: prune
    if (node.word != null) {
        found.add(node.word);
        node.word = null; // report each word only once
    }
    board[r][c] = '#'; // mark as used on the current path
    dfs(board, r - 1, c, node, found);
    dfs(board, r, c - 1, node, found);
    dfs(board, r + 1, c, node, found);
    dfs(board, r, c + 1, node, found);
    board[r][c] = ch; // backtrack: free the cell for other paths
    if (node.next.isEmpty() && node.word == null) parent.next.remove(ch); // prune a used-up leaf
}

static class TrieNode {
    Map<Character, TrieNode> next = new HashMap<>();
    String word; // non-null only where a word ends
}

